// The embedded vision code objects, one per GPU architecture of the build
// (generated by cmake/vision.cmake; gfx1151 since VIS-8S).
// SPDX-License-Identifier: Apache-2.0

#include "whirl/vision.h"

#if WHIRL_VISION_GFX1201
extern const unsigned char whirl_vision_gfx1201[];
extern const unsigned long long whirl_vision_gfx1201_size;
#endif
#if WHIRL_VISION_GFX1151
extern const unsigned char whirl_vision_gfx1151[];
extern const unsigned long long whirl_vision_gfx1151_size;
#endif

namespace whirl::vision {

std::span<const std::uint8_t> kernelImage(hip::Arch arch) {
    switch (arch) {
#if WHIRL_VISION_GFX1201
    case hip::Arch::gfx1201:
        return {whirl_vision_gfx1201, static_cast<std::size_t>(whirl_vision_gfx1201_size)};
#endif
#if WHIRL_VISION_GFX1151
    case hip::Arch::gfx1151:
        return {whirl_vision_gfx1151, static_cast<std::size_t>(whirl_vision_gfx1151_size)};
#endif
    default:
        return {};
    }
}

}  // namespace whirl::vision
